import sys
from collections import deque

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
caps = [int(x) for x in data[2:2 + m]]
trips = []
for i in range(m):
    trips.append(caps[i])
    for j in range(i + 1, m):
        trips.append(caps[i] + caps[j])
dist = {n: 0}
q = deque([n])
ans = -1
while q:
    r = q.popleft()
    if r == 0:
        ans = dist[r]
        break
    for t in trips:
        if t <= r and (r - t) not in dist:
            dist[r - t] = dist[r] + 1
            q.append(r - t)
print(ans)

